#include <Cellerator/compiler/diagnostics/benchmark_diagnostics_and_provenance_overhead_v1.hh>
#include <array>
namespace cellerator::compiler::diagnostics::v1 {namespace {bool within(std::uint64_t base,std::uint64_t value,std::uint32_t pct){return base&&value<=base+(base*pct)/100;}}bool provenance_overhead_within_budget(const std::vector<provenance_measurement>&m,provenance_budget b) noexcept{for(auto size:std::array{translation_unit_size::small,translation_unit_size::large}){const provenance_measurement*base=nullptr;for(auto&x:m)if(x.size==size&&x.level==provenance_level::disabled)base=&x;if(!base||!base->compile_ns||!base->peak_rss_bytes||!base->object_bytes)return false;for(auto&x:m)if(x.size==size){if(x.hot_runtime_bytes!=base->hot_runtime_bytes||!within(base->compile_ns,x.compile_ns,b.compile_percent)||!within(base->peak_rss_bytes,x.peak_rss_bytes,b.rss_percent)||!within(base->object_bytes,x.object_bytes,b.object_percent))return false;}}return true;}}
